// Generated by scripts/generate-articles.ts. Do not edit.
export default {"html":"<aside class=\"msg alert\"><span class=\"msg-symbol\">!</span><div class=\"msg-content\"><p data-line=\"1\" class=\"code-line\">This article was drafted by generative AI from <a href=\"https://www.youtube.com/watch?v=xAkS4pnHqRs\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.youtube.com/watch?v=xAkS4pnHqRs</a> as source material, then reviewed and edited by the author.</p>\n</div></aside>\n<h2 id=\"angular-v19-has-been-released!\" data-line=\"4\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#angular-v19-has-been-released!\" aria-hidden=\"true\"></a> Angular v19 Has Been Released!</h2>\n<p data-line=\"6\" class=\"code-line\">The Angular team has pushed standalone components and Signals hard over recent releases, and v19 is finally a major turning point. Personally, I think these changes will significantly improve the Angular developer experience.</p>\n<h2 id=\"standalone-components-are-now-the-default\" data-line=\"8\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#standalone-components-are-now-the-default\" aria-hidden=\"true\"></a> Standalone components are now the default</h2>\n<p data-line=\"10\" class=\"code-line\">Until now, creating a standalone component required <code>standalone: true</code> every time. Honestly, that was annoying.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"12\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  selector: </span><span style=\"color:#9ECBFF\">'app-example'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  templateUrl: </span><span style=\"color:#9ECBFF\">'./example.component.html'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  styleUrls: [</span><span style=\"color:#9ECBFF\">'./example.component.scss'</span><span style=\"color:#E1E4E8\">],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  standalone: </span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\">,  </span><span style=\"color:#a0aab5\">// This was required</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  imports: [CommonModule, FormsModule]</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ExampleComponent</span><span style=\"color:#E1E4E8\"> {}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"23\" class=\"code-line\">From v19, that is no longer required. Every component is standalone by default.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"25\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  selector: </span><span style=\"color:#9ECBFF\">'app-example'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  templateUrl: </span><span style=\"color:#9ECBFF\">'./example.component.html'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  styleUrls: [</span><span style=\"color:#9ECBFF\">'./example.component.scss'</span><span style=\"color:#E1E4E8\">],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  imports: [CommonModule, FormsModule]</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ExampleComponent</span><span style=\"color:#E1E4E8\"> {}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"35\" class=\"code-line\">Migrating from NgModule-based code to standalone components is easier now. Migration tooling is available too, so existing projects can move with confidence.</p>\n<h2 id=\"angular-signals-reach-stable\" data-line=\"37\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#angular-signals-reach-stable\" aria-hidden=\"true\"></a> Angular Signals reach stable</h2>\n<p data-line=\"39\" class=\"code-line\">I keep saying Signal-Based Reactivity is the best—and now <code>signal</code> and <code>computed</code> have moved from Developer Preview to stable. I can use them in production with confidence.</p>\n<p data-line=\"41\" class=\"code-line\">These Signal APIs are also production-ready:</p>\n<ul data-line=\"43\" class=\"code-line\">\n<li data-line=\"43\" class=\"code-line\">input</li>\n<li data-line=\"44\" class=\"code-line\">model</li>\n<li data-line=\"45\" class=\"code-line\">output</li>\n<li data-line=\"46\" class=\"code-line\">viewChild</li>\n<li data-line=\"47\" class=\"code-line\">viewChildren</li>\n<li data-line=\"48\" class=\"code-line\">contentChildren</li>\n<li data-line=\"49\" class=\"code-line\">contentChild</li>\n</ul>\n<p data-line=\"51\" class=\"code-line\">For example, I can define Signal-based inputs like this:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"53\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  selector: </span><span style=\"color:#9ECBFF\">'app-counter'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template: </span><span style=\"color:#9ECBFF\">`</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;p&gt;Count: {{ count() }}&lt;/p&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;button (click)=\"increment()\"&gt;Increment&lt;/button&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">  `</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> CounterComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // Signal-based input</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  count</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> input</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  increment</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // Set a new value</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.count.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">count</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#F97583\">+</span><span style=\"color:#79B8FF\"> 1</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"new-experimental-apis\" data-line=\"72\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#new-experimental-apis\" aria-hidden=\"true\"></a> New experimental APIs</h2>\n<p data-line=\"74\" class=\"code-line\">v19 introduces <code>linkSignal</code> and <code>resource</code> as new experimental APIs. They are still experimental, but I am quite excited about them.</p>\n<p data-line=\"76\" class=\"code-line\"><code>linkSignal</code> creates local state linked to a computed expression, making it easier to manage state based on computed values.</p>\n<p data-line=\"78\" class=\"code-line\"><code>resource</code> is a Signal API for asynchronous values such as server data, simplifying fetch and management of async data.</p>\n<aside class=\"msg message\"><span class=\"msg-symbol\">!</span><div class=\"msg-content\"><p data-line=\"81\" class=\"code-line\">These APIs are experimental, but I recommend trying them actively. Tooling is also available to help adopt Signals in projects.</p>\n</div></aside>\n<h2 id=\"major-angular-material-updates\" data-line=\"84\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#major-angular-material-updates\" aria-hidden=\"true\"></a> Major Angular Material updates</h2>\n<p data-line=\"86\" class=\"code-line\">Angular Material received a big update too. The standout is the brand-new <code>mat.theme</code> API.</p>\n<h3 id=\"new-theme-system\" data-line=\"88\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#new-theme-system\" aria-hidden=\"true\"></a> New theme system</h3>\n<p data-line=\"90\" class=\"code-line\">The new theme system is much simpler. Theme setup that used to take a lot of code is now a single call to <code>mat.theme</code>.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"92\"><span class=\"line\"><span style=\"color:#a0aab5\">// Previous theme configuration</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">@use</span><span style=\"color:#9ECBFF\"> '@angular/material'</span><span style=\"color:#F97583\"> as</span><span style=\"color:#FFAB70\"> mat</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">@include</span><span style=\"color:#FFAB70\"> mat</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">core</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">$my-primary</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#FFAB70\">mat</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#79B8FF\">define-palette</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">mat</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#FFAB70\">$indigo-palette</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">500</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">$my-accent</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#FFAB70\">mat</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#79B8FF\">define-palette</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">mat</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#FFAB70\">$pink-palette</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">A200</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">A100</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">A400</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">$my-warn</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#FFAB70\">mat</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#79B8FF\">define-palette</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">mat</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#FFAB70\">$red-palette</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">$my-theme</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#FFAB70\">mat</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#79B8FF\">define-light-theme</span><span style=\"color:#E1E4E8\">((</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  color</span><span style=\"color:#E1E4E8\">: (</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    primary: </span><span style=\"color:#FFAB70\">$my-primary</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    accent: </span><span style=\"color:#FFAB70\">$my-accent</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    warn: </span><span style=\"color:#FFAB70\">$my-warn</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  ),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  typography: </span><span style=\"color:#FFAB70\">mat</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#79B8FF\">define-typography-config</span><span style=\"color:#E1E4E8\">(),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  density: </span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">));</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">@include</span><span style=\"color:#FFAB70\"> mat</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">all-component-themes</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">$my-theme</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// New theme configuration</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">@use</span><span style=\"color:#9ECBFF\"> '@angular/material'</span><span style=\"color:#F97583\"> as</span><span style=\"color:#FFAB70\"> mat</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">@include</span><span style=\"color:#FFAB70\"> mat</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">theme</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"></span></code></pre></div><h3 id=\"overriding-component-styles\" data-line=\"118\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#overriding-component-styles\" aria-hidden=\"true\"></a> Overriding component styles</h3>\n<p data-line=\"120\" class=\"code-line\">For developers who want to customize Angular Material components, a new API using the <code>mat-theme-override mixin</code> is available.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"122\"><span class=\"line\"><span style=\"color:#F97583\">@use</span><span style=\"color:#9ECBFF\"> '@angular/material'</span><span style=\"color:#F97583\"> as</span><span style=\"color:#FFAB70\"> mat</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">@include</span><span style=\"color:#FFAB70\"> mat</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">theme</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// Override the button styles</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">@include</span><span style=\"color:#FFAB70\"> mat</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">theme-override</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  .mat-mdc-button</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    border-radius</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">24</span><span style=\"color:#F97583\">px</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><h3 id=\"time-picker-added\" data-line=\"135\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#time-picker-added\" aria-hidden=\"true\"></a> Time picker added</h3>\n<p data-line=\"137\" class=\"code-line\">The long-awaited <code>Time picker</code> is here, giving a standard UI component for time selection.</p>\n<h2 id=\"incremental-hydration\" data-line=\"139\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#incremental-hydration\" aria-hidden=\"true\"></a> Incremental hydration</h2>\n<p data-line=\"141\" class=\"code-line\">An important v19 feature is incremental hydration—Angular's next-generation hydration technology.</p>\n<p data-line=\"143\" class=\"code-line\">With incremental hydration, the main template can be rendered on the server and sent to the client still in a non-hydrated state. Then, based on application logic, parts of the template can be hydrated dynamically.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"145\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template: </span><span style=\"color:#9ECBFF\">`</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;header&gt;Static header (not hydrated)&lt;/header&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    </span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    @defer (on viewport) {</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;app-interactive-component&gt;&lt;/app-interactive-component&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    }</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    </span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    @defer (never) {</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;app-static-content&gt;&lt;/app-static-content&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    }</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    </span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;footer&gt;Static footer (not hydrated)&lt;/footer&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">  `</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> AppComponent</span><span style=\"color:#E1E4E8\"> {}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"164\" class=\"code-line\">This reduces overhead for static content and improves performance.</p>\n<h2 id=\"summary\" data-line=\"166\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"168\" class=\"code-line\">Angular v19 is an update that significantly improves the developer experience. Default standalone components, stable Signals, new experimental APIs, Angular Material improvements, and incremental hydration make Angular a more powerful, easier framework.</p>\n<p data-line=\"170\" class=\"code-line\">Personally, I am especially happy that Signal-Based Reactivity is stable—I can use it in production with confidence.</p>\n<p data-line=\"172\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"angular-v19-has-been-released!","text":"Angular v19 Has Been Released!","level":2},{"id":"standalone-components-are-now-the-default","text":"Standalone components are now the default","level":2},{"id":"angular-signals-reach-stable","text":"Angular Signals reach stable","level":2},{"id":"new-experimental-apis","text":"New experimental APIs","level":2},{"id":"major-angular-material-updates","text":"Major Angular Material updates","level":2},{"id":"new-theme-system","text":"New theme system","level":3},{"id":"overriding-component-styles","text":"Overriding component styles","level":3},{"id":"time-picker-added","text":"Time picker added","level":3},{"id":"incremental-hydration","text":"Incremental hydration","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
